import type {
  AddCorpusRequest,
  AnalyzeSelectionRequest,
  CollocationResponse,
  CorpusEntry,
  DocumentAnalysisRequest,
  DocumentAnalysisResponse,
  KwicResponse,
  LanguageInsight,
  NotePage,
  NoteSpace,
  PracticeTurnRequest,
  PracticeTurnResponse,
  VisionNoteRequest,
  VisionNoteResponse,
} from "@inkflow/shared";

const API_BASE = import.meta.env.VITE_API_URL || "";

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  const response = await fetch(`${API_BASE}${path}`, {
    ...init,
    headers: {
      "Content-Type": "application/json",
      ...init?.headers,
    },
  });

  if (!response.ok) {
    const payload = (await response.json().catch(() => null)) as
      | { message?: string; error?: string }
      | null;
    throw new Error(
      payload?.message ?? payload?.error ?? `Request failed: ${response.status}`,
    );
  }

  return (await response.json()) as T;
}

export const api = {
  health() {
    return request<{
      ok: boolean;
      deepseekConfigured: boolean;
      redisConfigured: boolean;
      databaseConfigured: boolean;
    }>("/health");
  },

  spaces() {
    return request<{ spaces: NoteSpace[] }>("/v1/spaces");
  },

  pages(noteId: string) {
    return request<{ pages: NotePage[] }>(`/v1/notes/${noteId}/pages`);
  },

  page(noteId: string, pageId: string) {
    return request<{ page: NotePage }>(
      `/v1/notes/${noteId}/pages/${pageId}`,
    );
  },

  savePage(
    noteId: string,
    pageId: string,
    page: Partial<NotePage> & { baseVersion?: number },
  ) {
    return request<{ page: NotePage }>(
      `/v1/notes/${noteId}/pages/${pageId}`,
      {
        method: "PUT",
        body: JSON.stringify(page),
      },
    );
  },

  createPage(noteId: string, page: Partial<NotePage>) {
    return request<{ page: NotePage }>(`/v1/notes/${noteId}/pages`, {
      method: "POST",
      body: JSON.stringify(page),
    });
  },

  insight(payload: AnalyzeSelectionRequest) {
    return request<{ insight: LanguageInsight }>("/v1/insights", {
      method: "POST",
      body: JSON.stringify(payload),
    });
  },

  collocations(term: string, context?: string) {
    return request<CollocationResponse>("/v1/insights/collocations", {
      method: "POST",
      body: JSON.stringify({ term, context }),
    });
  },

  vision(payload: VisionNoteRequest) {
    return request<VisionNoteResponse>("/v1/vision/notes", {
      method: "POST",
      body: JSON.stringify(payload),
    });
  },

  corpus(query = "") {
    return request<{ entries: CorpusEntry[] }>(
      `/v1/corpus${query ? `?q=${encodeURIComponent(query)}` : ""}`,
    );
  },

  addCorpus(payload: AddCorpusRequest) {
    return request<{ entry: CorpusEntry }>("/v1/corpus", {
      method: "POST",
      body: JSON.stringify(payload),
    });
  },

  removeCorpus(id: string) {
    return request<{ ok: boolean }>(`/v1/corpus/${id}`, { method: "DELETE" });
  },

  favoriteCorpus(id: string) {
    return request<{ entry: CorpusEntry }>(
      `/v1/corpus/${id}/favorite`,
      { method: "PATCH" },
    );
  },

  kwic(query: string) {
    return request<KwicResponse>(
      `/v1/kwic?q=${encodeURIComponent(query)}&limit=50`,
    );
  },

  practice(payload: PracticeTurnRequest) {
    return request<PracticeTurnResponse>("/v1/practice/turns", {
      method: "POST",
      body: JSON.stringify(payload),
    });
  },

  dictionary(word: string) {
    return request<{ insight: LanguageInsight; fallback?: boolean }>(
      `/v1/dictionary/${encodeURIComponent(word)}`,
    );
  },

  dictionaryStatus() {
    return request<{
      available: boolean;
      name: string | null;
      wordCount: number;
      reason?: string;
    }>("/v1/dictionary/status");
  },

  analyzeDocument(payload: DocumentAnalysisRequest) {
    return request<DocumentAnalysisResponse>("/v1/documents/analyze", {
      method: "POST",
      body: JSON.stringify(payload),
    });
  },
};

