import {
  type HTMLAttributes,
  type ReactNode,
  useEffect,
  useRef,
} from "react";
import * as THREE from "three";
import { cn } from "../../lib/cn";
import { usePrefersReducedMotion } from "../../motion/usePrefersReducedMotion";

export type AmbientVariant = "fog" | "clouds";

export interface AmbientBackdropProps extends HTMLAttributes<HTMLDivElement> {
  variant: AmbientVariant;
  active: boolean;
  children?: ReactNode;
}

const FALLBACK_PALETTES: Record<AmbientVariant, string> = {
  fog: "linear-gradient(135deg, #f8f2e6 0%, #e3eff0 48%, #d5e3e8 100%)",
  clouds:
    "linear-gradient(150deg, #f7efe1 0%, #e7eef0 45%, #dce8e7 100%)",
};

export function getAmbientFallback(variant: AmbientVariant) {
  return FALLBACK_PALETTES[variant];
}

export function loadAmbientEffect(variant: AmbientVariant) {
  return variant === "fog"
    ? import("vanta/dist/vanta.fog.min")
    : import("vanta/dist/vanta.clouds2.min");
}

export function preloadAmbientEffects() {
  return Promise.allSettled([
    loadAmbientEffect("fog"),
    loadAmbientEffect("clouds"),
  ]);
}

export function resolveVantaFactory(module: unknown) {
  let candidate = module;
  while (
    candidate &&
    typeof candidate === "object" &&
    "default" in candidate
  ) {
    candidate = (candidate as { default: unknown }).default;
  }

  if (typeof candidate !== "function") {
    throw new TypeError("Vanta effect module did not expose a factory");
  }
  return candidate as (
    options: Record<string, unknown>,
  ) => InkflowVantaEffect;
}

export function createVantaNoiseDataUrl() {
  if (typeof document === "undefined") return "";
  const canvas = document.createElement("canvas");
  canvas.width = 64;
  canvas.height = 64;
  const context = canvas.getContext("2d");
  if (!context) return "";

  const image = context.createImageData(canvas.width, canvas.height);
  let seed = 739391;
  for (let index = 0; index < image.data.length; index += 4) {
    seed = (seed * 1664525 + 1013904223) >>> 0;
    const value = 48 + ((seed >>> 24) % 176);
    image.data[index] = value;
    image.data[index + 1] = value;
    image.data[index + 2] = value;
    image.data[index + 3] = 255;
  }
  context.putImageData(image, 0, 0);
  return canvas.toDataURL("image/png");
}

function getOptions(variant: AmbientVariant) {
  if (variant === "fog") {
    return {
      THREE,
      backgroundColor: 0xf2eee5,
      baseColor: 0xf8f3e9,
      lowlightColor: 0xb8d5d9,
      midtoneColor: 0xd5e6e5,
      highlightColor: 0xffffff,
      blurFactor: 0.72,
      speed: 0.72,
      zoom: 0.92,
      scale: 1.25,
      scaleMobile: 1.8,
      mouseControls: false,
      touchControls: false,
      gyroControls: false,
    };
  }

  return {
    THREE,
    backgroundColor: 0xf2eee5,
    skyColor: 0xe3ecec,
    cloudColor: 0xd6dfdf,
    lightColor: 0xffffff,
    speed: 0.48,
    texturePath: createVantaNoiseDataUrl(),
    scale: 1.2,
    scaleMobile: 1.7,
    mouseControls: false,
    touchControls: false,
    gyroControls: false,
  };
}

export function AmbientBackdrop({
  variant,
  active,
  children,
  className,
  style,
  ...props
}: AmbientBackdropProps) {
  const hostRef = useRef<HTMLDivElement>(null);
  const prefersReducedMotion = usePrefersReducedMotion();

  useEffect(() => {
    const host = hostRef.current;
    if (!active || !host || prefersReducedMotion) return undefined;

    let cancelled = false;
    let effect: InkflowVantaEffect | undefined;

    void loadAmbientEffect(variant)
      .then((module) => {
        const createEffect = resolveVantaFactory(module);
        if (cancelled || !hostRef.current) return;
        effect = createEffect({
          el: hostRef.current,
          ...getOptions(variant),
        });
      })
      .catch(() => {
        // The CSS backdrop remains visible when WebGL is unavailable.
      });

    return () => {
      cancelled = true;
      effect?.destroy();
      effect = undefined;
    };
  }, [active, prefersReducedMotion, variant]);

  return (
    <div
      {...props}
      className={cn("ambient-backdrop", className)}
      data-active={active ? "true" : "false"}
      data-variant={variant}
      style={{
        background: getAmbientFallback(variant),
        ...style,
      }}
    >
      <div
        ref={hostRef}
        className="ambient-backdrop__canvas"
        aria-hidden="true"
      />
      {children}
    </div>
  );
}
